import json
from collections import defaultdict

user_totals = defaultdict(float)
user_items = defaultdict(int)
tag_counts = defaultdict(int)

with open('/app/records_1.jsonl', 'r') as f:
    for line in f:
        record = json.loads(line.strip())
        user = record['user']
        user_totals[user] += record['amount']
        user_items[user] += record['items']
        for tag in record.get('tags', []):
            tag_counts[tag] += 1

# Also process other files
for i in range(2, 6):
    filepath = f'/app/records_{i}.jsonl'
    with open(filepath, 'r') as f:
        for line in f:
            record = json.loads(line.strip())
            user = record['user']
            user_totals[user] += record['amount']
            user_items[user] += record['items']
            for tag in record.get('tags', []):
                tag_counts[tag] += 1

# Sort users by total amount descending, then take top 5
sorted_users = sorted(user_totals.items(), key=lambda x: x[1], reverse=True)
top_5_users = {}
for i in range(min(5, len(sorted_users))):
    user, total_amount = sorted_users[i]
    total_items = user_items[user]
    top_5_users[user] = {
        "total_amount": round(total_amount, 2),
        "total_items": total_items
    }

# Sort tags by count descending, then take top 5
sorted_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)
top_5_tags = {}
for i in range(min(5, len(sorted_tags))):
    tag, count = sorted_tags[i]
    top_5_tags[tag] = {
        "count": count
    }

result = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

with open('/app/aggregates.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Aggregates written to /app/aggregates.json")
